public static class F1SunsetCheck {
 static string Out=>Path.GetFullPath(Application.dataPath+"/../../../Docs/Review/2026-11-13_1F_SunsetSky/");const string E="Assets/Afrer_Seconds/05.Model/Environment/1F/";
 public static object Refine(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_1F_Factory.unity"))throw new Exception("Saved 1F required");RenderSettings.ambientSkyColor=new Color(.40f,.38f,.49f);RenderSettings.ambientEquatorColor=new Color(.46f,.34f,.29f);RenderSettings.ambientGroundColor=new Color(.23f,.18f,.19f);EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);return new{ambientAdjusted=true,saved=true};}
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_1F_Factory.unity"))throw new Exception("Saved 1F required");var ts=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var map=ts.ToDictionary(t=>AnimationUtility.CalculateTransformPath(t,null));var before=JArray.Parse(File.ReadAllText(Out+"before_transforms.json"));string sun=AnimationUtility.CalculateTransformPath(RenderSettings.sun.transform,null);var changes=new List<string>();float[] V(Vector3 v)=>new[]{v.x,v.y,v.z};foreach(var b in before){string path=(string)b["path"];if(!map.TryGetValue(path,out var t)){changes.Add(path+" missing");continue;}foreach(var q in new[]{new{key="local",value=V(t.localPosition)},new{key="rotation",value=V(t.localEulerAngles)},new{key="scale",value=V(t.localScale)}}){if(path==sun&&q.key=="rotation")continue;var a=b[q.key].Values<float>().ToArray();if(q.value.Where((v,i)=>Mathf.Abs(v-a[i])>.00001f).Any())changes.Add(path+" "+q.key);}if((bool)b["active"]!=t.gameObject.activeSelf)changes.Add(path+" active");var c=JToken.FromObject(t.GetComponents<Collider>().Select(x=>new{type=x.GetType().Name,x.enabled}));if(!JToken.DeepEquals(c,b["colliders"]))changes.Add(path+" colliders");}
 var shader=AssetDatabase.LoadAssetAtPath<Shader>(E+"FS_SunsetSky.shader");var messages=ShaderUtil.GetShaderMessages(shader).Select(m=>new{m.message,severity=m.severity.ToString(),m.line}).ToArray();var result=new{scene=s.path,saved=!s.isDirty,playing=Application.isPlaying,runInBackground=Application.runInBackground,beforeTransforms=before.Count,transforms=ts.Length,allowedTransformChange=sun+" rotation",unexpectedTransformChanges=changes,colliders=ts.Sum(t=>t.GetComponents<Collider>().Length),shaderMessages=messages,shaderErrors=messages.Count(m=>m.severity=="Error"),missingMeshes=ts.SelectMany(t=>t.GetComponents<MeshFilter>()).Count(f=>!f.sharedMesh),missingMaterials=ts.SelectMany(t=>t.GetComponents<Renderer>()).Count(r=>r.sharedMaterials.Any(m=>!m||!m.shader)),missingScripts=ts.Sum(t=>GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject)),sky=AssetDatabase.GetAssetPath(RenderSettings.skybox)};File.WriteAllText(Out+"final_check.json",JsonConvert.SerializeObject(result,Formatting.Indented));Selection.activeObject=RenderSettings.skybox;SceneView.lastActiveSceneView?.LookAt(new Vector3(-145,6,-31.5f),Quaternion.LookRotation(new Vector3(-1,.063f,-.035f)),63,false,true);return result;}
